		fmt.Fprintf(ctx, "Invalid JSON: %v", err)
		return
	}

	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		fmt.Fprint(ctx, "URL is required")
		return
	}

