	json.NewEncoder(ctx).Encode(resp)
}

func parseHTML(body []byte) (string, string) {
	var title string
	var description string

	tokenizer := html.NewTokenizer(strings.NewReader(string(body)))

	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
