	"golang.org/x/net/html"
)

// URLPreviewRequest represents the incoming JSON request
type URLPreviewRequest struct {
	URL string `json:"url"`
}

// URLPreviewResponse represents the outgoing JSON response
type URLPreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST requests
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetBodyString("Method not allowed")
		return
	}

	// Parse the JSON body
	var req URLPreviewRequest
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		resp := URLPreviewResponse{Error: "Invalid JSON"}
		jsonResp, _ := json.Marshal(resp)
		ctx.SetContentType("application/json")
		ctx.SetBody(jsonResp)
		return
	}

	// Validate URL
	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		resp := URLPreviewResponse{Error: "URL is required"}
		jsonResp, _ := json.Marshal(resp)
		ctx.SetContentType("application/json")
		ctx.SetBody(jsonResp)
		return
	}

	// Fetch the URL with timeout
	title, description, err := fetchAndParseURL(req.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		resp := URLPreviewResponse{Error: fmt.Sprintf("Failed to fetch URL: %v", err)}
		jsonResp, _ := json.Marshal(resp)
		ctx.SetContentType("application/json")
		ctx.SetBody(jsonResp)
		return
	}

	// Return successful response
	resp := URLPreviewResponse{
		Title:       title,
		Description: description,
	}
	jsonResp, _ := json.Marshal(resp)
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(jsonResp)
}

func fetchAndParseURL(urlStr string) (string, string, error) {
	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(urlStr)
	req.Header.SetMethod("GET")
	req.Header.SetUserAgent("Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Use DoRedirects with a 3-second timeout
	err := httpClient.DoRedirects(req, resp, 5) // max redirects
	if err != nil {
		return "", "", fmt.Errorf("request failed: %w", err)
	}

	// Check status code
	statusCode := resp.StatusCode()
	if statusCode < 200 || statusCode >= 300 {
		return "", "", fmt.Errorf("HTTP status %d", statusCode)
	}

	// Get the body
	bodyBytes := resp.Body()
	bodyReader := io.Reader(strings.NewReader(string(bodyBytes)))

	// Parse HTML
	doc, err := html.Parse(bodyReader)
	if err != nil {
		return "", "", fmt.Errorf("HTML parse failed: %w", err)
	}

	title, description := extractTitleAndDescription(doc)
	return title, description, nil
}

func extractTitleAndDescription(n *html.Node) (string, string) {
	var title, description string
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				title = getTextContent(n)
			}
			if n.Data == "meta" {
				name := getAttr(n, "name")
				content := getAttr(n, "content")
				if strings.EqualFold(name, "description") && content != "" {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(n)
	return title, description
}

func getTextContent(n *html.Node) string {
	var textBuilder strings.Builder
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.TextNode {
			textBuilder.WriteString(n.Data)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(n)
	return strings.TrimSpace(textBuilder.String())
}

func getAttr(n *html.Node, key string) string {
	for _, attr := range n.Attr {
		if strings.EqualFold(attr.Key, key) {
			return attr.Val
		}
	}
	return ""
}

func main() {
	server := &fasthttp.Server{
		Handler:      FetchURLPreview,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 5 * time.Second,
	}

	fmt.Println("Server starting on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

