import (
	"encoding/json"
	"fmt"
	"io"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// PreviewResponse represents the JSON response structure
type PreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// FetchURLPreview handles POST requests to fetch URL preview data
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST method
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		return
	}

	// Parse JSON body
	var requestBody struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &requestBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid JSON"}`))
		return
	}

	url := strings.TrimSpace(requestBody.URL)
	if url == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"url is required"}`))
		return
	}

	// Create fasthttp client with DualStack dialer
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Prepare request
	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(url)
	req.Header.SetMethod("GET")

	// Fetch the URL with redirects
	err := client.DoRedirects(req, resp, 5)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(fmt.Sprintf(`{"error":"failed to fetch URL: %s"}`, err.Error())))
		return
	}

	// Check if content type is HTML
	contentType := string(resp.Header.ContentType())
	if !strings.Contains(strings.ToLower(contentType), "text/html") {
		ctx.SetStatusCode(fasthttp.StatusUnsupportedMediaType)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"URL does not return HTML content"}`))
		return
	}

	// Parse HTML to extract title and meta description
	title, description := parseHTML(resp.Body())

	// Build response
	response := PreviewResponse{
		Title:       title,
		Description: description,
	}

	jsonResponse, err := json.Marshal(response)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"failed to marshal response"}`))
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(jsonResponse)
}

// parseHTML extracts title and meta description from HTML content
func parseHTML(body []byte) (string, string) {
	title := ""
	description := ""

	tokenizer := html.NewTokenizer(io.NopCloser(strings.NewReader(string(body))))

	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			return title, description
		case html.StartTagToken, html.SelfClosingTagToken:
			token := tokenizer.Token()
			switch token.Data {
			case "title":
				// Read text inside title tag
				tt = tokenizer.Next()
				if tt == html.TextToken {
					title = strings.TrimSpace(tokenizer.Token().Data)
				}
			case "meta":
				// Check for meta description
				nameAttr := ""
				contentAttr := ""
				for _, attr := range token.Attr {
					switch strings.ToLower(attr.Key) {
					case "name", "property":
						nameAttr = strings.ToLower(attr.Val)
					case "content":
						contentAttr = attr.Val
					}
				}
				if nameAttr == "description" || nameAttr == "og:description" {
					if description == "" || nameAttr == "description" {
						description = strings.TrimSpace(contentAttr)
					}
				}
			}
		}
	}
}

func main() {
	server := &fasthttp.Server{
		Handler: FetchURLPreview,
	}

	fmt.Println("Server starting on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		panic(err)
	}
}

