// FetchURLPreview handles POST requests to fetch URL preview data
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !bytes.Equal(ctx.Method(), []byte("POST")) {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetBodyString("Method not allowed")
		return
	}

	// Parse JSON body
	var requestBody struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &requestBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString("Invalid JSON body")
		return
	}

	targetURL := requestBody.URL
	if targetURL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString("URL is required")
		return
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(targetURL)
	if err != nil || parsedURL.Scheme == "" || parsedURL.Host == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString("Invalid URL format")
		return
	}

	// Create fasthttp client with dual stack dial and 3 second timeout
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
		ReadTimeout:  3 * time.Second,
		WriteTimeout: 3 * time.Second,
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(targetURL)
	req.Header.SetMethod("GET")
	req.Header.SetUserAgent("Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	err = client.DoRedirects(req, resp, 10) // Allow up to 10 redirects

	if err != nil {
		// Check if it's a timeout error
		if strings.Contains(err.Error(), "timeout") {
			ctx.SetStatusCode(fasthttp.StatusGatewayTimeout)
			ctx.SetBodyString("Request timed out")
		} else {
