// parseHTML extracts title and meta description from HTML content
func parseHTML(htmlContent string) (string, string) {
	var title string
	var description string

	tokenizer := html.NewTokenizer(strings.NewReader(htmlContent))
	inTitle := false

	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
