package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"log"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// URLPreviewRequest represents the incoming JSON request
type URLPreviewRequest struct {
	URL string `json:"url"`
}

// URLPreviewResponse represents the outgoing JSON response
type URLPreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// ErrorResponse represents an error response
type ErrorResponse struct {
	Error string `json:"error"`
}

var client = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only accept POST requests
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		writeJSONError(ctx, "Method not allowed")
		return
	}

	// Parse the JSON body
	var req URLPreviewRequest
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		writeJSONError(ctx, "Invalid JSON body")
		return
	}

	// Validate URL
	url := strings.TrimSpace(req.URL)
	if url == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		writeJSONError(ctx, "URL is required")
		return
	}

	// Fetch the URL content
	reqFasthttp := fasthttp.AcquireRequest()
	respFasthttp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(reqFasthttp)
	defer fasthttp.ReleaseResponse(respFasthttp)

	reqFasthttp.SetRequestURI(url)
	reqFasthttp.Header.SetMethod("GET")

	err := client.DoRedirects(reqFasthttp, respFasthttp, 10)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		writeJSONError(ctx, fmt.Sprintf("Failed to fetch URL: %v", err))
		return
	}

	statusCode := respFasthttp.StatusCode()
	if statusCode < 200 || statusCode >= 300 {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		writeJSONError(ctx, fmt.Sprintf("Received non-2xx status code: %d", statusCode))
		return
	}

	contentType := string(respFasthttp.Header.ContentType())
	if !strings.Contains(strings.ToLower(contentType), "text/html") {
		ctx.SetStatusCode(fasthttp.StatusUnsupportedMediaType)
		writeJSONError(ctx, "Content type is not HTML")
		return
	}

	bodyBytes := respFasthttp.Body()
	title, description := parseHTMLTitleAndDescription(bodyBytes)

	response := URLPreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	jsonData, _ := json.Marshal(response)
	ctx.Write(jsonData)
}

func writeJSONError(ctx *fasthttp.RequestCtx, message string) {
	errResp := ErrorResponse{Error: message}
	ctx.SetContentType("application/json")
	jsonData, _ := json.Marshal(errResp)
	ctx.Write(jsonData)
}

func parseHTMLTitleAndDescription(body []byte) (string, string) {
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return "", ""
	}

	var title, description string
	var findTitleAndDescription func(*html.Node)
	findTitleAndDescription = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				title = extractText(n)
			}
			if n.Data == "meta" {
				nameAttr := getAttribute(n, "name")
				propertyAttr := getAttribute(n, "property")
				contentAttr := getAttribute(n, "content")
				if strings.EqualFold(nameAttr, "description") && contentAttr != "" {
					description = contentAttr
				}
				if strings.EqualFold(propertyAttr, "og:description") && contentAttr != "" {
					if description == "" {
						description = contentAttr
					}
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			findTitleAndDescription(c)
		}
	}

	findTitleAndDescription(doc)
	return title, description
}

func extractText(n *html.Node) string {
	var buf bytes.Buffer
	var traverse func(*html.Node)
	traverse = func(node *html.Node) {
		if node.Type == html.TextNode {
			buf.WriteString(node.Data)
		}
		for c := node.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(n)
	return strings.TrimSpace(buf.String())
}

func getAttribute(n *html.Node, key string) string {
	for _, attr := range n.Attr {
		if strings.EqualFold(attr.Key, key) {
			return attr.Val
		}
	}
	return ""
}

func main() {
	mux := &fasthttp.ServeMux{}
	mux.Handle("/fetch-url-preview", fasthttp.RequestHandler(FetchURLPreview))

	log.Println("Server starting on :8080")
	if err := fasthttp.ListenAndServe(":8080", mux); err != nil {
		log.Fatalf("Error in ListenAndServe: %v", err)
	}
