func safeDialFunc() fasthttp.DialFunc {
	return func(addr string) (net.Conn, error) {
		host, port, err := net.SplitHostPort(addr)
		if err != nil {
			// If SplitHostPort fails, it might be because there's no port.
			// Try to parse as just a host and use default port 80 or 443? 
			// Actually, fasthttp usually provides addr with port.
			// Let's try to resolve it anyway.
			host = addr
