		}

		ips, err := net.LookupIP(host)
		if err != nil {
			return nil, fmt.Errorf("failed to lookup IP: %w", err)
		}

		for _, ip := range ips {
			if isPrivateIP(ip) {
				return nil, fmt.Errorf("access to private IP addresses is forbidden")
			}
		}

		// Reconstruct address for dialing
		dialAddr := net.JoinHostPort(host, port)
		conn, err := net.DialTimeout("tcp", dialAddr, 10*time.Second)
