// safeDialFunc returns a dial function that prevents SSRF attacks by checking IP addresses.
func safeDialFunc() fasthttp.DialFunc {
	return func(addr string) (net.Conn, error) {
		host, _, err := net.SplitHostPort(addr)
		if err != nil {
			// If no port is specified, use default ports based on scheme if available, but here we just return error or try to parse host only
			host = addr
		}

		ips, err := net.LookupIP(host)
		if err != nil {
			return nil, fmt.Errorf("failed to lookup IP for %s: %w", host, err)
		}

		for _, ip := range ips {
			if isPrivateOrLoopback(ip) {
				return nil, fmt.Errorf("access to private or loopback addresses is forbidden")
			}
		}

		dialer := &net.Dialer{
			Timeout: 10 * time.Second,
		}
		conn, err := dialer.Dial("tcp", addr)
		if err != nil {
			return nil, err
		}
		return conn, nil
	}
}

// isPrivateOrLoopback checks if an IP address is private, loopback, or link-local.
func isPrivateOrLoopback(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}
	if ip.To4() != nil {
		return ip.IsPrivate()
	}
	return false
}

