	"golang.org/x/net/html"
)

// RequestBody represents the incoming JSON request body
type RequestBody struct {
	URL string `json:"url"`
}

// PreviewResponse represents the JSON response with title and description
type PreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

var client *fasthttp.Client

func init() {
	client = &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"method not allowed"}`))
		return
	}

	var reqBody RequestBody
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &reqBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid json"}`))
		return
	}

	if reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"url is required"}`))
		return
	}

	title, description, err := fetchAndParse(reqBody.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		resp, _ := json.Marshal(map[string]string{"error": err.Error()})
		ctx.SetBody(resp)
		return
	}

	response := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	resp, _ := json.Marshal(response)
	ctx.SetBody(resp)
}

func fetchAndParse(urlStr string) (string, string, error) {
	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(urlStr)
	req.Header.SetMethod("GET")
	req.Header.SetUserAgent("Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	err := client.DoRedirects(req, resp, 5)
	if err != nil {
		return "", "", fmt.Errorf("failed to fetch URL: %w", err)
	}

	statusCode := resp.StatusCode()
	if statusCode != fasthttp.StatusOK {
		return "", "", fmt.Errorf("unexpected status code: %d", statusCode)
	}

	body := resp.Body()
	if len(body) == 0 {
		return "", "", fmt.Errorf("empty response body")
	}

	return parseHTML(string(body))
}

func parseHTML(content string) (string, string, error) {
	doc, err := html.Parse(strings.NewReader(content))
	if err != nil {
		return "", "", fmt.Errorf("failed to parse HTML: %w", err)
	}

	var title, description string
	titleFound := false
	descriptionFound := false

	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "title":
				if !titleFound && n.FirstChild != nil {
					title = n.FirstChild.Data
					titleFound = true
				}
			case "meta":
				if !descriptionFound {
					nameAttr := ""
					contentAttr := ""
					for _, attr := range n.Attr {
						if attr.Key == "name" || attr.Key == "property" {
							nameAttr = strings.ToLower(attr.Val)
						}
						if attr.Key == "content" {
							contentAttr = attr.Val
						}
					}
					if nameAttr == "description" || nameAttr == "og:description" {
						description = contentAttr
						descriptionFound = true
					}
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}

	f(doc)

	return title, description, nil
}

func main() {
	server := &fasthttp.Server{
		Handler: FetchURLPreview,
		Name:    "URLPreviewServer",
		ReadTimeout:  3 * time.Second,
		WriteTimeout: 3 * time.Second,
	}

	fmt.Println("Starting server on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

