	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Prepare request
	fastReq := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(fastReq)
	fastReq.SetRequestURI(req.URL)
	fastReq.Header.SetMethod("GET")
	fastReq.Header.SetUserAgent("Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Prepare response
	fastResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(fastResp)

	// Execute request with redirects support
	err := client.DoRedirects(fastReq, fastResp, 5)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		resp := URLPreviewResponse{Error: fmt.Sprintf("Failed to fetch URL: %v", err)}
		jsonResp, _ := json.Marshal(resp)
		ctx.Write(jsonResp)
		return
	}

	// Check status code
	statusCode := fastResp.StatusCode()
	if statusCode != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		resp := URLPreviewResponse{Error: fmt.Sprintf("Received non-200 status code: %d", statusCode)}
		jsonResp, _ := json.Marshal(resp)
		ctx.Write(jsonResp)
		return
	}

