// extractTitleAndDescription parses HTML and extracts title and meta description
func extractTitleAndDescription(r io.Reader) (string, string, error) {
	tokenizer := html.NewTokenizer(r)

	var title string
	var description string
	inTitle := false

	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			err := tokenizer.Err()
			if err == io.EOF {
				return title, description, nil
			}
			return "", "", err
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName, hasAttr := tokenizer.TagName()
			tagNameStr := string(tagName)

			if tagNameStr == "title" {
				inTitle = true
			} else if tagNameStr == "meta" && hasAttr {
				attrs := getAttributes(tokenizer)
				name := attrs["name"]
				content := attrs["content"]

				// Check for meta description
				if strings.EqualFold(name, "description") || strings.EqualFold(name, "og:description") {
					description = content
				}
			}
		case html.TextToken:
			if inTitle {
				title += string(tokenizer.Text())
			}
		case html.EndTagToken:
			tagName, _ := tokenizer.TagName()
			if string(tagName) == "title" {
				inTitle = false
			}
		}
	}
}

// getAttributes extracts attributes from the current token
func getAttributes(tokenizer *html.Tokenizer) map[string]string {
	attrs := make(map[string]string)
	for {
		key, val, more := tokenizer.TagAttr()
		if key == nil {
			break
		}
		attrs[string(key)] = string(val)
		if !more {
			break
		}
	}
	return attrs
}

