	if statusCode != http.StatusOK {
		ctx.SetStatusCode(statusCode)
		ctx.SetBodyString(fmt.Sprintf(`{"error": "HTTP error: %d"}`, statusCode))
		return
	}

	contentType := string(resp.Header.ContentType())
	if !strings.Contains(strings.ToLower(contentType), "text/html") {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error": "Content is not HTML"}`)
		return
	}

	bodyBytes := resp.Body()
	title, description := parseHTML(bodyBytes)

	response := PreviewResponse{
		Title:       title,
		Description: description,
	}

	jsonResp, err := json.Marshal(response)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBodyString(`{"error": "Failed to marshal response"}`)
		return
	}

	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(jsonResp)
}

func parseHTML(body []byte) (string, string) {
	var title, description string
	tokenizer := html.NewTokenizer(bytes.NewReader(body))

	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			return title, description
		case html.StartTagToken, html.SelfClosingTagToken:
			token := tokenizer.Token()
			if token.Data == "title" {
				// Read until end tag
				for {
					tt := tokenizer.Next()
					if tt == html.TextToken {
						title += tokenizer.Token().Data
					} else if tt == html.EndTagToken {
						break
					} else if tt == html.ErrorToken {
						return title, description
					}
				}
			} else if token.Data == "meta" {
				name := ""
				content := ""
				for _, attr := range token.Attr {
					if attr.Key == "name" || attr.Key == "property" {
						name = strings.ToLower(attr.Val)
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" || name == "og:description" {
					if description == "" || name == "description" {
						description = content
					}
				}
			}
		}
	}
}

func main() {
	log.Println("Starting server on :8080")
	err := fasthttp.ListenAndServe(":8080", func(ctx *fasthttp.RequestCtx) {
		FetchURLPreview(ctx)
	})
	if err != nil {
		log.Fatalf("Error starting server: %v", err)
	}
}

