// URLPreviewRequest represents the incoming JSON request body
type URLPreviewRequest struct {
	URL string `json:"url"`
}

// URLPreviewResponse represents the outgoing JSON response body
type URLPreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

// fetchHTMLContent fetches the HTML content from the given URL using fasthttp client
func fetchHTMLContent(urlStr string) ([]byte, error) {
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(urlStr)
	req.Header.SetMethod("GET")

	// Set timeout for the request
	err := client.DoRedirects(req, resp, 5)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch URL: %w", err)
	}

	statusCode := resp.StatusCode()
	if statusCode != fasthttp.StatusOK {
		return nil, fmt.Errorf("unexpected status code: %d", statusCode)
	}

	body := resp.Body()
	// Copy the body since it will be released
	result := make([]byte, len(body))
	copy(result, body)

	return result, nil
}

// extractTitleAndDescription parses HTML and extracts title and meta description
func extractTitleAndDescription(htmlContent []byte) (string, string) {
	var title string
	var description string

	doc, err := html.Parse(bytes.NewReader(htmlContent))
	if err != nil {
		return "", ""
	}

	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode && n.Data == "title" {
			if n.FirstChild != nil {
				title = strings.TrimSpace(n.FirstChild.Data)
			}
		}
		if n.Type == html.ElementNode && n.Data == "meta" {
			nameAttr := ""
			contentAttr := ""
			for _, attr := range n.Attr {
				if attr.Key == "name" || attr.Key == "property" {
					nameAttr = strings.ToLower(attr.Val)
				}
				if attr.Key == "content" {
					contentAttr = attr.Val
				}
			}
			if nameAttr == "description" || nameAttr == "og:description" {
				if contentAttr != "" {
					description = strings.TrimSpace(contentAttr)
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)

	return title, description
}

// FetchURLPreview handles POST requests with a JSON body containing a URL
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST method
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetContentType("application/json")
		resp := URLPreviewResponse{Error: "Only POST method is allowed"}
		json.NewEncoder(ctx).Encode(resp)
		return
	}

	// Parse the request body
	var reqBody URLPreviewRequest
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &reqBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		resp := URLPreviewResponse{Error: "Invalid JSON body"}
		json.NewEncoder(ctx).Encode(resp)
		return
	}

	// Validate URL
	if reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		resp := URLPreviewResponse{Error: "URL field is required"}
		json.NewEncoder(ctx).Encode(resp)
		return
	}

	// Fetch the HTML content
	htmlContent, err := fetchHTMLContent(reqBody.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		resp := URLPreviewResponse{Error: fmt.Sprintf("Failed to fetch URL: %v", err)}
		json.NewEncoder(ctx).Encode(resp)
		return
	}

	// Extract title and description
	title, description := extractTitleAndDescription(htmlContent)

	// Prepare response
	resp := URLPreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	json.NewEncoder(ctx).Encode(resp)
}

func main() {
	// Create a simple server to test the handler
	server := &fasthttp.Server{
		Handler: FetchURLPreview,
		Name:    "URL Preview Server",
	}

	fmt.Println("Server starting on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

