func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		return
	}

	var req URLPreviewRequest
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid json"}`))
		return
	}

	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"url is required"}`))
		return
	}

	// Validate URL format
	if !strings.HasPrefix(req.URL, "http://") && !strings.HasPrefix(req.URL, "https://") {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid url scheme"}`))
		return
	}

	// Fetch the URL content using DoRedirects to follow redirects
	reqFastHTTP := fasthttp.AcquireRequest()
	respFastHTTP := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(reqFastHTTP)
	defer fasthttp.ReleaseResponse(respFastHTTP)

	reqFastHTTP.SetRequestURI(req.URL)
	reqFastHTTP.Header.SetMethod("GET")
	reqFastHTTP.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Use DoRedirects with a reasonable redirect limit
	err := httpClient.DoRedirects(reqFastHTTP, respFastHTTP, 5)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(fmt.Sprintf(`{"error":"failed to fetch url: %s"}`, err.Error())))
		return
	}

	statusCode := respFastHTTP.StatusCode()
	if statusCode < 200 || statusCode >= 300 {
		ctx.SetStatusCode(statusCode)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(fmt.Sprintf(`{"error":"received status code %d"}`, statusCode)))
		return
	}

	contentType := string(respFastHTTP.Header.ContentType())
	if !strings.Contains(strings.ToLower(contentType), "text/html") {
		ctx.SetStatusCode(fasthttp.StatusUnsupportedMediaType)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"content is not html"}`))
		return
	}

	bodyBytes := respFastHTTP.Body()
	title, description := parseHTMLMeta(string(bodyBytes))

	response := URLPreviewResponse{
		Title:       title,
		Description: description,
	}

	jsonResp, err := json.Marshal(response)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"failed to marshal response"}`))
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(jsonResp)
}

// parseHTMLMeta extracts the title and meta description from HTML content.
func parseHTMLMeta(htmlContent string) (string, string) {
	tokenizer := html.NewTokenizer(strings.NewReader(htmlContent))
	var title string
	var description string

	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			return title, description
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName := string(tokenizer.Token().Data)
			if tagName == "title" {
				// Read until end tag
				tt = tokenizer.Next()
				if tt == html.TextToken {
					title = strings.TrimSpace(string(tokenizer.Token().Data))
				}
			} else if tagName == "meta" {
				var nameAttr, contentAttr string
				for _, attr := range tokenizer.Token().Attr {
					if strings.EqualFold(attr.Key, "name") || strings.EqualFold(attr.Key, "property") {
						nameAttr = attr.Val
					}
					if strings.EqualFold(attr.Key, "content") {
						contentAttr = attr.Val
					}
				}
				if strings.EqualFold(nameAttr, "description") {
					description = strings.TrimSpace(contentAttr)
				}
			}
		}
	}
}

func main() {
	server := &fasthttp.Server{
		Handler:      FetchURLPreview,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	log.Println("Starting server on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		log.Fatalf("Error in ListenAndServe: %v", err)
	}
}

