// safeDial creates a dial function that prevents SSRF attacks by blocking private and loopback addresses.
func safeDial(addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, fmt.Errorf("invalid address: %w", err)
	}

	ip := net.ParseIP(host)
	if ip == nil {
		// If it's not an IP, resolve it first to check
		addrs, err := net.LookupIP(host)
		if err != nil {
			return nil, fmt.Errorf("failed to resolve host: %w", err)
		}
		for _, addr := range addrs {
			if isPrivateOrLoopback(addr) {
				return nil, fmt.Errorf("access to private or loopback addresses is forbidden")
			}
		}
		// Use the first valid public IP for connection
		// Note: In production, you might want to connect to each until one works, 
		// but for simplicity and security, we just ensure none are private.
		// We'll let the standard dialer handle the actual connection after validation.
	} else {
		if isPrivateOrLoopback(ip) {
			return nil, fmt.Errorf("access to private or loopback addresses is forbidden")
		}
	}

	// Reconstruct address with resolved IP if needed, or use original if domain
	dialAddr := addr
	if ip == nil {
		// Resolve again to get a concrete IP for dialing, ensuring we don't hit a private IP
		addrs, err := net.LookupIP(host)
		if err != nil || len(addrs) == 0 {
			return nil, fmt.Errorf("failed to resolve host")
		}
		var publicIP net.IP
		for _, a := range addrs {
			if !isPrivateOrLoopback(a) {
				publicIP = a
				break
			}
		}
		if publicIP == nil {
			return nil, fmt.Errorf("no public IP found for host")
		}
		dialAddr = net.JoinHostPort(publicIP.String(), port)
	}

	conn, err := net.DialTimeout("tcp", dialAddr, 10*time.Second)
	if err != nil {
		return nil, err
	}
	return conn, nil
}

func isPrivateOrLoopback(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}
	return false
}

// FetchURLPreview handles POST requests to fetch URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST
	if ctx.IsPost() {
		var req struct {
			URL string `json:"url"`
		}

		body := ctx.PostBody()
		if err := json.Unmarshal(body, &req); err != nil {
			ctx.Error("Invalid JSON", fasthttp.StatusBadRequest)
			return
		}

		targetURL := strings.TrimSpace(req.URL)
		if targetURL == "" {
			ctx.Error("URL is required", fasthttp.StatusBadRequest)
			return
		}

		// Validate URL scheme
		parsedURL, err := url.ParseRequestURI(targetURL)
		if err != nil {
			ctx.Error("Invalid URL format", fasthttp.StatusBadRequest)
			return
		}

		if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
			ctx.Error("URL must use http or https scheme", fasthttp.StatusBadRequest)
			return
		}

		// Use fasthttp.Client to fetch with timeout and secure dialer
		client := &fasthttp.Client{
			Dial:                safeDial,
			ReadTimeout:         10 * time.Second,
			WriteTimeout:        10 * time.Second,
			MaxIdleConnDuration: 10 * time.Second,
			MaxConnsPerHost:     10,
		}

		freq := fasthttp.AcquireRequest()
		res := fasthttp.AcquireResponse()
		defer fasthttp.ReleaseRequest(freq)
		defer fasthttp.ReleaseResponse(res)

		freq.SetRequestURI(targetURL)
		freq.Header.SetMethod("GET")
		freq.Header.Set("User-Agent", "URLPreviewBot/1.0")

		maxRedirectCounts := 10
		if err := client.DoRedirects(freq, res, maxRedirectCounts); err != nil {
			ctx.Error(fmt.Sprintf("Failed to fetch URL: %v", err), fasthttp.StatusBadGateway)
			return
		}

		if res.StatusCode() != fasthttp.StatusOK {
			ctx.Error(fmt.Sprintf("Unexpected status code: %d", res.StatusCode()), fasthttp.StatusBadGateway)
			return
		}

		bodyBytes := res.Body()
		if len(bodyBytes) == 0 {
			ctx.Error("Empty response body", fasthttp.StatusBadGateway)
			return
		}

		title, description, err := parseHTMLPreview(bytes.NewReader(bodyBytes))
		if err != nil {
			ctx.Error(fmt.Sprintf("Failed to parse HTML: %v", err), fasthttp.StatusInternalServerError)
			return
		}

		resp := PreviewResponse{
			Title:       title,
			Description: description,
		}

		ctx.SetContentType("application/json; charset=utf-8")
		if err := json.NewEncoder(ctx).Encode(resp); err != nil {
			ctx.Error("Failed to encode response", fasthttp.StatusInternalServerError)
			return
		}
	} else {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
	}
