// PreviewResult holds the extracted title and description
type PreviewResult struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// FetchURLPreview handles POST requests to fetch URL preview data
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST method
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		return
	}

	// Parse JSON body
	var reqBody struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid JSON"}`))
		return
	}

	if reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"url is required"}`))
		return
	}

	// Create a fasthttp client with DualStack dialer
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Prepare the request
	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod("GET")

	// Use DoRedirects to follow redirects (max 10 redirects)
	err := client.DoRedirects(req, resp, 10)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(fmt.Sprintf(`{"error":"failed to fetch URL: %s"}`, err.Error())))
		return
	}

	// Check if response is HTML
	contentType := string(resp.Header.ContentType())
	if !strings.Contains(strings.ToLower(contentType), "text/html") {
		ctx.SetStatusCode(fasthttp.StatusOK)
		ctx.SetContentType("application/json")
		result := PreviewResult{
			Title:       "",
			Description: "",
		}
		data, _ := json.Marshal(result)
		ctx.SetBody(data)
		return
	}

	// Parse HTML to extract title and meta description
	body := resp.Body()
	title, description := parseHTML(string(body))

	// Return result as JSON
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	result := PreviewResult{
		Title:       title,
		Description: description,
	}
	data, _ := json.Marshal(result)
	ctx.SetBody(data)
}

// parseHTML extracts the title and meta description from HTML content
func parseHTML(htmlContent string) (string, string) {
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return "", ""
	}

	var title, description string
	findMetaTags(doc, &title, &description)
	return title, description
}

// findMetaTags recursively searches for title and meta description tags
func findMetaTags(n *html.Node, title, description *string) {
	if n.Type == html.ElementNode {
		switch n.Data {
		case "title":
			if *title == "" {
				*title = getTextContent(n)
			}
		case "meta":
			var name, content string
			for _, attr := range n.Attr {
				if strings.EqualFold(attr.Key, "name") && strings.EqualFold(attr.Val, "description") {
					name = attr.Val
				}
				if strings.EqualFold(attr.Key, "content") {
					content = attr.Val
				}
			}
			if name == "description" && *description == "" {
				*description = content
			}
		}
	}

	for c := n.FirstChild; c != nil; c = c.NextSibling {
		findMetaTags(c, title, description)
	}
}

// getTextContent extracts text content from an HTML node
func getTextContent(n *html.Node) string {
	var buf strings.Builder
	extractText(n, &buf)
	return strings.TrimSpace(buf.String())
}

// extractText recursively extracts text from HTML nodes
func extractText(n *html.Node, buf *strings.Builder) {
	if n.Type == html.TextNode {
		buf.WriteString(n.Data)
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		extractText(c, buf)
	}
}

func main() {
	mux := &fasthttp.RequestHandler{}
	*mux = func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/preview":
			FetchURLPreview(ctx)
		default:
			ctx.NotFound()
		}
	}

	fmt.Println("Server starting on :8080")
	if err := fasthttp.ListenAndServe(":8080", mux); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

